begin;
create table public.assessment_analytics_snapshots(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),window_id uuid not null,cohort_id uuid,cohort_revision integer,
 title text not null,threshold_percent numeric(9,6) not null check(threshold_percent between 0 and 100),population jsonb not null,source_hash text not null check(source_hash~'^[a-f0-9]{64}$'),
 created_by uuid not null references public.users(id),reason text not null check(length(reason) between 1 and 2000),as_of timestamptz not null,unique(tenant_id,id),foreign key(tenant_id,window_id) references public.assessment_exam_windows(tenant_id,id)
);
create table public.assessment_analytics_rows(
 tenant_id uuid not null,snapshot_id uuid not null,attempt_id uuid not null,score_revision_id uuid not null references public.assessment_score_revisions(id),generation integer not null,released_at timestamptz not null,
 form_key text not null check(form_key~'^[a-f0-9]{64}$'),scores jsonb not null,total numeric not null,maximum numeric not null check(maximum>0 and total between 0 and maximum),responses jsonb not null,
 primary key(snapshot_id,attempt_id),foreign key(tenant_id,snapshot_id) references public.assessment_analytics_snapshots(tenant_id,id)
);
create index assessment_analytics_form on public.assessment_analytics_rows(snapshot_id,form_key,attempt_id);
create table public.assessment_analytics_items(
 tenant_id uuid not null,snapshot_id uuid not null,item_version_id uuid not null,prompt text not null,type text not null,locale text not null,options jsonb not null,
 primary key(snapshot_id,item_version_id),foreign key(tenant_id,snapshot_id) references public.assessment_analytics_snapshots(tenant_id,id)
);
create table public.assessment_analytics_commands(tenant_id uuid not null,actor_id uuid not null,idempotency_key text not null,request jsonb not null,result jsonb not null,primary key(tenant_id,actor_id,idempotency_key));
do $$ declare t text;begin foreach t in array array['assessment_analytics_snapshots','assessment_analytics_rows','assessment_analytics_items','assessment_analytics_commands'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from anon,authenticated',t);execute format('create trigger immutable_record before update or delete on public.%I for each row execute function public.assessment_immutable()',t);end loop;end;$$;
create function public.assessment_analytics_allowed(p_tenant uuid,p_actor uuid) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select public.assessment_has_capability(p_tenant,p_actor,'results.read') and public.assessment_has_capability(p_tenant,p_actor,'banks.read');$$;
create function public.assessment_analytics_command(p_actor uuid,p_tenant uuid,p_key text,p_data jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare prior public.assessment_analytics_commands;win public.assessment_exam_windows;grp public.assessment_cohorts;stamp timestamptz:=clock_timestamp();sid uuid:=gen_random_uuid();counted jsonb;source text;result jsonb;
begin
 if p_key is null or length(p_key) not between 8 and 200 or p_data is null or jsonb_typeof(p_data)<>'object' then raise exception 'invalid_analytics_command' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('assessment.staff:'||p_tenant::text,0));if not public.assessment_analytics_allowed(p_tenant,p_actor) then raise exception 'forbidden' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_tenant::text||p_actor::text||'analytics'||p_key,0));
 select * into prior from public.assessment_analytics_commands where tenant_id=p_tenant and actor_id=p_actor and idempotency_key=p_key;if found then if prior.request<>p_data then raise exception 'idempotency_conflict' using errcode='23505';end if;return prior.result;end if;
 select * into win from public.assessment_exam_windows where tenant_id=p_tenant and id=(p_data->>'window_id')::uuid;if not found then raise exception 'sitting_not_found' using errcode='P0002';end if;
 if p_data->>'cohort_id' is not null then select * into grp from public.assessment_cohorts where tenant_id=p_tenant and id=(p_data->>'cohort_id')::uuid for share;if not found then raise exception 'cohort_not_found' using errcode='P0002';end if;end if;
 stamp:=clock_timestamp();
 -- One statement materializes the entire population and eligible latest release set.
 -- No attempt/candidate names, answer keys or response text enter a report row.
 with population as(select g.id,a.id attempt_id,a.state from public.assessment_registrations g left join public.assessment_attempts a on a.registration_id=g.id where g.tenant_id=p_tenant and g.window_id=win.id and (grp.id is null or exists(select 1 from public.assessment_cohort_members m where m.cohort_id=grp.id and m.user_id=g.candidate_id and m.active))),
 eligible as(select distinct on(r.attempt_id) r.attempt_id,r.generation,l.score_revision_id,l.release_at from public.assessment_grading_runs r join public.assessment_grading_releases l on l.run_id=r.id where r.tenant_id=p_tenant and l.release_at<=stamp and exists(select 1 from population p where p.attempt_id=r.attempt_id) order by r.attempt_id,r.generation desc),
 pinned as(select e.*,v.scores,f.manifest from eligible e join public.assessment_score_revisions v on v.id=e.score_revision_id join public.assessment_attempts a on a.id=e.attempt_id join public.assessment_forms f on f.id=a.form_id),
 inserted as(insert into public.assessment_analytics_rows(tenant_id,snapshot_id,attempt_id,score_revision_id,generation,released_at,form_key,scores,total,maximum,responses)
 select p_tenant,sid,p.attempt_id,p.score_revision_id,p.generation,p.release_at,
 encode(sha256(convert_to((select jsonb_agg(jsonb_build_object('id',s->>'item_version_id','maximum',trim_scale((s->>'max_score')::numeric)) order by s->>'item_version_id') from jsonb_array_elements(p.scores)s)::text,'UTF8')),'hex'),
 (select jsonb_agg(jsonb_build_object('item_version_id',s->>'item_version_id','score',(s->>'score')::numeric,'max_score',(s->>'max_score')::numeric) order by s->>'item_version_id') from jsonb_array_elements(p.scores)s),
 (select sum((s->>'score')::numeric) from jsonb_array_elements(p.scores)s),(select sum((s->>'max_score')::numeric) from jsonb_array_elements(p.scores)s),
 (select coalesce(jsonb_object_agg(s->>'item_version_id',jsonb_build_object('recorded',coalesce(r.response not in('null'::jsonb,'""'::jsonb,'[]'::jsonb,'{}'::jsonb),false),'selected',case when iv.payload->>'type' in('single_choice','multi_choice','true_false') then (select coalesce(jsonb_agg(o->>'id'),'[]') from jsonb_array_elements(iv.payload->'options')o where (jsonb_typeof(r.response)='string' and r.response#>>'{}'=o->>'id') or (jsonb_typeof(r.response)='array' and r.response ? (o->>'id'))) else '[]'::jsonb end)),'{}') from jsonb_array_elements(p.scores)s join public.assessment_item_versions iv on iv.id=(s->>'item_version_id')::uuid and iv.tenant_id=p_tenant left join lateral(select response from public.assessment_response_journal where attempt_id=p.attempt_id and item_version_id=iv.id order by sequence desc limit 1)r on true)
 from pinned p returning attempt_id)
 select jsonb_build_object('registered',count(*),'started',count(attempt_id),'finalized',count(*) filter(where state in('submitted','expired')),'released',(select count(*) from inserted),'cohort_title',grp.title,'cohort_membership_basis',case when grp.id is null then null else 'active cohort entries at report creation' end) into counted from population;
 -- The FK is deferred only during this transaction's materialization, never left dangling.
 select encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('attempt_id',attempt_id,'score_revision_id',score_revision_id,'generation',generation,'form_key',form_key,'scores',scores,'responses',responses) order by attempt_id),'[]')::text,'UTF8')),'hex') into source from public.assessment_analytics_rows where snapshot_id=sid;
 insert into public.assessment_analytics_snapshots(id,tenant_id,window_id,cohort_id,cohort_revision,title,threshold_percent,population,source_hash,created_by,reason,as_of) values(sid,p_tenant,win.id,grp.id,grp.revision,win.title,(p_data->>'threshold_percent')::numeric,counted,source,p_actor,p_data->>'reason',stamp);
 if exists(select 1 from public.assessment_analytics_rows ar join public.assessment_attempts a on a.id=ar.attempt_id join public.assessment_forms f on f.id=a.form_id where ar.snapshot_id=sid and (jsonb_array_length(ar.scores)=0 or jsonb_array_length(ar.scores)<>(select count(*) from jsonb_array_elements(f.manifest->'sections')sec cross join lateral jsonb_array_elements(sec->'items')i) or (select count(distinct s->>'item_version_id') from jsonb_array_elements(ar.scores)s)<>jsonb_array_length(ar.scores) or exists(select 1 from jsonb_array_elements(ar.scores)s where s->'score'='null'::jsonb or (s->>'score')::numeric not between 0 and (s->>'max_score')::numeric or (s->>'max_score')::numeric<=0 or not exists(select 1 from jsonb_array_elements(f.manifest->'sections')sec cross join lateral jsonb_array_elements(sec->'items')i where i->>'item_version_id'=s->>'item_version_id')))) then raise exception 'invalid_released_score_snapshot' using errcode='23514';end if;
 if exists(select 1 from public.assessment_analytics_rows ar cross join lateral jsonb_array_elements(ar.scores)s left join public.assessment_item_versions iv on iv.id=(s->>'item_version_id')::uuid and iv.tenant_id=p_tenant join public.assessment_score_revisions sv on sv.id=ar.score_revision_id where ar.snapshot_id=sid and (iv.id is null or (iv.payload->>'max_score')::numeric<>(s->>'max_score')::numeric or sv.attempt_id<>ar.attempt_id or sv.tenant_id<>p_tenant or sv.status<>'approved')) then raise exception 'invalid_released_score_snapshot' using errcode='23514';end if;
 insert into public.assessment_analytics_items select distinct p_tenant,sid,iv.id,iv.payload->>'prompt',iv.payload->>'type',iv.payload->>'locale',case when iv.payload->>'type' in('single_choice','multi_choice','true_false') then coalesce(iv.payload->'options','[]') else '[]'::jsonb end from public.assessment_analytics_rows ar cross join lateral jsonb_array_elements(ar.scores)s join public.assessment_item_versions iv on iv.id=(s->>'item_version_id')::uuid and iv.tenant_id=p_tenant where ar.snapshot_id=sid;
 result:=jsonb_build_object('id',sid);insert into public.assessment_analytics_commands values(p_tenant,p_actor,p_key,p_data,result);insert into public.assessment_audit_events(tenant_id,actor_id,action,target_id,details) values(p_tenant,p_actor,'analytics.snapshot.created',sid,jsonb_build_object('window_id',win.id,'cohort_id',grp.id,'released',counted->'released','source_hash',source));return result;
end;$$;
-- Rows are inserted before their immutable header so the header hash includes the
-- canonical row set, while both remain one atomic transaction.
alter table public.assessment_analytics_rows drop constraint assessment_analytics_rows_tenant_id_snapshot_id_fkey;
alter table public.assessment_analytics_rows add foreign key(tenant_id,snapshot_id) references public.assessment_analytics_snapshots(tenant_id,id) deferrable initially deferred;
create function public.assessment_analytics_report(p_id uuid,p_form text,p_after uuid,p_limit integer) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare snap public.assessment_analytics_snapshots;summary jsonb;items jsonb;forms jsonb;reliability jsonb;chosen text;groups integer;
begin
 select * into snap from public.assessment_analytics_snapshots where id=p_id;
 select count(distinct form_key),min(form_key) into groups,chosen from public.assessment_analytics_rows where snapshot_id=p_id;chosen:=case when p_form is not null then p_form when groups=1 then chosen else null end;
 if p_form is not null and not exists(select 1 from public.assessment_analytics_rows where snapshot_id=p_id and form_key=p_form) then raise exception 'form_not_found' using errcode='P0002';end if;
 with selected as(select *,100*total/maximum percent from public.assessment_analytics_rows where snapshot_id=p_id and (p_form is null or form_key=p_form))
 select jsonb_build_object('count',count(*),'mean_percent',avg(percent),'median_percent',percentile_cont(.5) within group(order by percent),'sd_percent',stddev_samp(percent),'minimum_percent',min(percent),'maximum_percent',max(percent),'at_or_above_threshold',count(*) filter(where percent>=snap.threshold_percent),'distribution',(select jsonb_agg(jsonb_build_object('from_percent',b*10,'to_percent',(b+1)*10,'count',(select count(*) from selected where least(9,floor(percent/10))=b)) order by b) from generate_series(0,9)b)) into summary from selected;
 select coalesce(jsonb_agg(to_jsonb(g) order by form_key),'[]') into forms from(select form_key,count(*) sample_size,jsonb_array_length(min(scores::text)::jsonb) item_count from public.assessment_analytics_rows where snapshot_id=p_id group by form_key order by form_key limit 100)g;
 if chosen is not null then
  with valueset as(select ar.attempt_id,ar.total,s->>'item_version_id' item_id,(s->>'score')::numeric points,(s->>'max_score')::numeric maximum,ar.responses from public.assessment_analytics_rows ar cross join lateral jsonb_array_elements(ar.scores)s where ar.snapshot_id=p_id and ar.form_key=chosen),
  stats as(select item_id,count(*) n,var_samp(points) variance,avg(points/maximum)*100 mean_percent,count(*) filter(where points=maximum) full_credit,count(*) filter(where coalesce((responses->item_id->>'recorded')::boolean,false)) recorded,case when count(*)>=5 then corr(points::double precision,(total-points)::double precision) else null end item_rest_correlation from valueset group by item_id)
  select coalesce(jsonb_agg(jsonb_build_object('id',m.item_version_id,'prompt',m.prompt,'type',m.type,'locale',m.locale,'sample_size',s.n,'mean_percent',s.mean_percent,'full_credit',s.full_credit,'recorded',s.recorded,'item_rest_correlation',s.item_rest_correlation,'options',(select coalesce(jsonb_agg(jsonb_build_object('id',o->>'id','text',o->>'text','selected',(select count(*) from valueset v where v.item_id=s.item_id and v.responses->s.item_id->'selected' ? (o->>'id')))),'[]') from jsonb_array_elements(m.options)o)) order by m.item_version_id),'[]') into items from(select * from stats where p_after is null or item_id::uuid>p_after order by item_id::uuid limit p_limit)s join public.assessment_analytics_items m on m.snapshot_id=p_id and m.item_version_id=s.item_id::uuid;
  with item_variances as(select s->>'item_version_id' id,var_samp((s->>'score')::numeric) variance from public.assessment_analytics_rows ar cross join lateral jsonb_array_elements(ar.scores)s where ar.snapshot_id=p_id and ar.form_key=chosen group by s->>'item_version_id'), totals as(select count(*) n,var_samp(total) variance from public.assessment_analytics_rows where snapshot_id=p_id and form_key=chosen)
  select jsonb_build_object('sample_size',n,'item_count',(select count(*) from item_variances),'raw_alpha',case when n>=5 and variance>0 and (select count(*) from item_variances)>1 then (select count(*)::numeric/(count(*)-1)*(1-sum(item_variances.variance)/totals.variance) from item_variances) else null end,'method','raw point-score alpha; identical selected item versions and maxima; no imputation or reverse scoring') into reliability from totals;
 else items:='[]';reliability:=null;end if;
 return to_jsonb(snap)-array['created_by']||jsonb_build_object('summary',summary,'forms',forms,'form_count',groups,'selected_form',chosen,'items',items,'reliability',reliability,'cautions',jsonb_build_array('Released results only; latest eligible generation per attempt at the report time.','The analysis cutoff is not an official pass/fail decision.','Different randomized forms are not equated; item diagnostics require one identical item set.','Small samples and internal consistency do not establish validity, fairness or calibrated difficulty.'));
end;$$;
create function public.assessment_analytics_read(p_actor uuid,p_tenant uuid,p_kind text,p_id uuid default null,p_form text default null,p_after uuid default null,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 if not public.assessment_analytics_allowed(p_tenant,p_actor) then raise exception 'forbidden' using errcode='42501';end if;
 if p_limit is null or p_limit not between 1 and 100 then raise exception 'invalid_analytics_page' using errcode='22023';end if;
 if p_kind='sittings' then return(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from(select id,title,opens_at,closes_at from public.assessment_exam_windows where tenant_id=p_tenant and (p_after is null or id>p_after) order by id limit p_limit)t);end if;
 if p_kind='cohorts' then return(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from(select id,title,revision,state from public.assessment_cohorts where tenant_id=p_tenant and (p_after is null or id>p_after) order by id limit p_limit)t);end if;
 if p_kind='snapshots' then return(select coalesce(jsonb_agg(to_jsonb(t) order by id),'[]') from(select id,title,as_of,population,cohort_id from public.assessment_analytics_snapshots where tenant_id=p_tenant and (p_after is null or id>p_after) order by id limit p_limit)t);end if;
 if p_kind='forms' and exists(select 1 from public.assessment_analytics_snapshots where tenant_id=p_tenant and id=p_id) then return(select coalesce(jsonb_agg(to_jsonb(t) order by form_key),'[]') from(select form_key,count(*) sample_size,jsonb_array_length(min(scores::text)::jsonb) item_count from public.assessment_analytics_rows where snapshot_id=p_id and (p_form is null or form_key>p_form) group by form_key order by form_key limit p_limit)t);end if;
 if p_kind<>'report' or not exists(select 1 from public.assessment_analytics_snapshots where tenant_id=p_tenant and id=p_id) then raise exception 'report_not_found' using errcode='P0002';end if;
 return public.assessment_analytics_report(p_id,p_form,p_after,p_limit);
end;$$;
create function public.assessment_released_breakdown(p_actor uuid,p_tenant uuid,p_attempt uuid) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$
declare released record;form jsonb;sections jsonb;
begin
 select r.generation,l.score_revision_id,l.release_at,v.scores into released from public.assessment_attempts a join public.assessment_grading_runs r on r.attempt_id=a.id join public.assessment_grading_releases l on l.run_id=r.id join public.assessment_score_revisions v on v.id=l.score_revision_id where a.tenant_id=p_tenant and a.candidate_id=p_actor and a.id=p_attempt and l.release_at<=clock_timestamp() order by r.generation desc limit 1;if not found then raise exception 'released_result_not_found' using errcode='P0002';end if;
 select f.manifest into form from public.assessment_attempts a join public.assessment_forms f on f.id=a.form_id where a.id=p_attempt;
 select jsonb_agg(jsonb_build_object('title',section->>'title','position',position,'total',(select sum((score->>'score')::numeric) from jsonb_array_elements(released.scores)score where exists(select 1 from jsonb_array_elements(section->'items')i where i->>'item_version_id'=score->>'item_version_id')),'max_score',(select sum((score->>'max_score')::numeric) from jsonb_array_elements(released.scores)score where exists(select 1 from jsonb_array_elements(section->'items')i where i->>'item_version_id'=score->>'item_version_id')),'questions',(select jsonb_agg(jsonb_build_object('position',n,'score',score->'score','max_score',score->'max_score') order by n) from jsonb_array_elements(section->'items') with ordinality items(i,n) join lateral(select value score from jsonb_array_elements(released.scores) where value->>'item_version_id'=i->>'item_version_id')sc on true)) order by position) into sections from jsonb_array_elements(form->'sections') with ordinality parts(section,position);
 return jsonb_build_object('attempt_id',p_attempt,'generation',released.generation,'score_revision_id',released.score_revision_id,'released_at',released.release_at,'sections',sections);
end;$$;
-- Extend access discovery without altering existing capabilities or role versions.
alter function public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) rename to assessment_grading_read_pre_analytics;
create function public.assessment_grading_read(p_actor uuid,p_tenant uuid,p_kind text,p_id uuid default null,p_after uuid default null,p_limit integer default 100) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin if p_kind='access' then return public.assessment_grading_read_pre_analytics(p_actor,p_tenant,p_kind,p_id,p_after,p_limit)||jsonb_build_object('can_read_analytics',public.assessment_analytics_allowed(p_tenant,p_actor));end if;return public.assessment_grading_read_pre_analytics(p_actor,p_tenant,p_kind,p_id,p_after,p_limit);end;$$;
revoke all on function public.assessment_analytics_allowed(uuid,uuid),public.assessment_analytics_report(uuid,text,uuid,integer),public.assessment_analytics_command(uuid,uuid,text,jsonb),public.assessment_analytics_read(uuid,uuid,text,uuid,text,uuid,integer),public.assessment_released_breakdown(uuid,uuid,uuid),public.assessment_grading_read_pre_analytics(uuid,uuid,text,uuid,uuid,integer),public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) from public,anon,authenticated;
grant execute on function public.assessment_analytics_command(uuid,uuid,text,jsonb),public.assessment_analytics_read(uuid,uuid,text,uuid,text,uuid,integer),public.assessment_released_breakdown(uuid,uuid,uuid),public.assessment_grading_read(uuid,uuid,text,uuid,uuid,integer) to service_role;
commit;
